/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LoadMechanicsKernelOptions, loadMechanicsKernel, loadMechanicsContext, resolveMechanicsRepoRoot
 * depends    src/mechanics/coverage/schema, src/mechanics/debug-graph, src/mechanics/doctor/diagnose, src/mechanics/ep-graph, src/mechanics/kernel/schema, src/mechanics/repo-root (+2 more)
 * used by    src/mechanics/kernel/index, src/mechanics/kernel/validate, src/mechanics/registry/build
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import fs from 'node:fs'
import path from 'node:path'
import {
  CoverageInventorySchema,
  coverageStatusCounts,
  findSilentGaps,
  type CoverageInventory,
} from '../coverage/schema'
import { loadDebugGraphDegraded } from '../debug-graph'
import { diagnoseDoctor } from '../doctor/diagnose'
import { loadEpGraph } from '../ep-graph'
import { resolveMechanicsRepoRoot } from '../repo-root'
import { loadSaveGraphDegraded } from '../save-graph'
import { loadCommitGraphDegraded } from '@tmrxjd/governance-engine'
import {
  buildSdkGraphIndex,
  loadSdkGraphWithTrust,
  type TrustMode,
} from '../sdk-graph'
import {
  MechanicsContextSchema,
  type MechanicsContext,
  type MechanicsKernelHandle,
} from './schema'

export { resolveMechanicsRepoRoot } from '../repo-root'

export interface LoadMechanicsKernelOptions {
  repoRoot?: string
  mode?: TrustMode
  /** Include Doctor diagnosis (adds cost; default true for CLI/MCP). */
  includeDoctor?: boolean
  scanPlannerCitations?: boolean
  checkDebugGraph?: boolean
}

function loadInventoryFile(filePath: string): CoverageInventory | null {
  if (!fs.existsSync(filePath)) return null
  try {
    return CoverageInventorySchema.parse(JSON.parse(fs.readFileSync(filePath, 'utf8')))
  } catch {
    return null
  }
}

function summarizeInventory(inv: CoverageInventory | null) {
  if (!inv) {
    return { entryCount: 0, silentGapCount: 0, counts: {} as Record<string, number> }
  }
  return {
    entryCount: inv.entries.length,
    silentGapCount: findSilentGaps(inv).length,
    counts: coverageStatusCounts(inv),
  }
}

/**
 * Unified mechanics load: graphs + trust + coverage (+ optional doctor).
 * Graph is SoT for relationships; this facade does not invent facts.
 */
export function loadMechanicsKernel(
  opts: LoadMechanicsKernelOptions = {},
): MechanicsKernelHandle {
  const repoRoot = resolveMechanicsRepoRoot(opts.repoRoot)
  const mode = opts.mode ?? 'degraded'
  const includeDoctor = opts.includeDoctor !== false

  const { graph: sdkGraph, report: trust, trust: trustLabel } = loadSdkGraphWithTrust({
    mode,
    scanPlannerCitations: opts.scanPlannerCitations ?? true,
    checkDebugGraph: opts.checkDebugGraph ?? true,
  })
  const epGraph = loadEpGraph()
  const dbg = loadDebugGraphDegraded()
  const save = loadSaveGraphDegraded()
  const commit = loadCommitGraphDegraded(repoRoot)
  const index = buildSdkGraphIndex(sdkGraph)

  const coverageDir = path.join(repoRoot, 'packages/sdk/src/mechanics/coverage/data')
  const inventories: Record<string, CoverageInventory | null> = {
    sheets: loadInventoryFile(path.join(coverageDir, 'sheets.v1.json')),
    'sdk-modules': loadInventoryFile(path.join(coverageDir, 'sdk-modules.v1.json')),
    wiki: loadInventoryFile(path.join(coverageDir, 'wiki.v1.json')),
    'save-schema': loadInventoryFile(path.join(coverageDir, 'save-schema.v1.json')),
  }

  let doctorStatus: MechanicsContext['doctorStatus']
  if (includeDoctor) {
    doctorStatus = diagnoseDoctor({ repoRoot, skipDriftFiles: false }).status
  }

  const debugNodes = Object.values(dbg.graph.nodes)
  const debugSymbolCount = debugNodes.filter(n => n.type === 'runtime.symbol').length
  const debugModuleCount = debugNodes.filter(n => n.type === 'runtime.module').length

  const surfaces: MechanicsContext['coverage']['surfaces'] = {}
  for (const [key, inv] of Object.entries(inventories)) {
    surfaces[key] = summarizeInventory(inv)
  }

  const context = MechanicsContextSchema.parse({
    generatedAt: new Date().toISOString(),
    constitution: 'docs/AGENT_MECHANICS_CONSTITUTION.md',
    trustLabel,
    doctorStatus,
    graphs: {
      sdk: {
        nodeCount: Object.keys(sdkGraph.nodes).length,
        edgeCount: sdkGraph.edges.length,
        contentVersion: sdkGraph.contentVersion,
        sheetVersion: sdkGraph.sheetVersion,
      },
      ep: {
        nodeCount: Object.keys(epGraph.nodes).length,
        edgeCount: epGraph.edges.length,
        contentVersion: epGraph.contentVersion,
        sheetVersion: epGraph.sheetVersion,
      },
      debug: {
        nodeCount: Object.keys(dbg.graph.nodes).length,
        edgeCount: dbg.graph.edges.length,
        contentVersion: dbg.graph.contentVersion,
        errors: dbg.errors,
        warnings: dbg.warnings,
      },
      save: {
        nodeCount: Object.keys(save.graph.nodes).length,
        edgeCount: save.graph.edges.length,
        contentVersion: save.graph.contentVersion,
        errors: save.errors,
        warnings: save.warnings,
      },
      commit: {
        nodeCount: Object.keys(commit.graph.nodes).length,
        edgeCount: commit.graph.edges.length,
        errors: commit.errors,
        warnings: commit.warnings,
      },
    },
    coverage: { surfaces },
    indexHints: {
      cellCount: Object.keys(index.byCell).length,
      wikiCount: Object.keys(index.byWiki).length,
      symbolCount: Object.keys(index.bySymbol).length,
      debugSymbolCount,
      debugModuleCount,
    },
    trustOk: trust.ok,
    ok:
      trust.ok
      && dbg.errors.length === 0
      && save.errors.length === 0
      && commit.errors.length === 0
      && (doctorStatus === undefined || doctorStatus !== 'broken'),
  })

  return {
    context,
    trust,
    doctorStatus,
    sdkGraph,
    epGraph,
    debugGraph: dbg.graph,
    saveGraph: save.graph,
    commitGraph: commit.graph,
    inventories: inventories as Record<string, unknown>,
  }
}

/** Convenience: context summary only. */
export function loadMechanicsContext(opts: LoadMechanicsKernelOptions = {}): MechanicsContext {
  return loadMechanicsKernel(opts).context
}
